using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;using EchoSphere.Core;using EchoSphere.Runtime;using EchoSphere.Presentation;
public static class ArchiveArtifactBuildCheck {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");int checks=0;void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);object Call(object o,string n,params object[] a)=>o.GetType().GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);
 var owner=new GameObject("Owned artifact build check");owner.SetActive(false);var runtime=owner.AddComponent<EchoSphereRuntime>();runtime.enabled=false;owner.SetActive(true);Set(runtime,"_knowledgeLoaded",true);Set(runtime,"_shopSaveLoaded",true);Set(runtime,"_shopSave",Activator.CreateInstance(typeof(EchoSphereRuntime).GetNestedType("ShopSaveData",F)));var catalog=Resources.Load<NativeArchiveCatalog>("EchoSphere/NativeArchiveCatalog");Set(runtime,"_sourceKnowledge",catalog);Set(runtime,"_knowledgeSection","artifacts");var known=(HashSet<string>)typeof(EchoSphereRuntime).GetField("_knownKnowledgeIds",F).GetValue(runtime);foreach(var artifact in ArtifactRewardRules.Catalog(true))known.Add("artifact:"+artifact.Id);
 var screens=new List<NativeArchiveScreen.State>();
 try{foreach(bool ru in new[]{true,false}){var state=(NativeArchiveScreen.State)Call(runtime,"ReadNativeArchiveState");state.Russian=ru;foreach(var card in state.Cards){var item=ArtifactRewardRules.Get(card.Id.Substring(9));card.Title=ru?item.NameRussian:item.NameEnglish;card.Description=ru?item.DescriptionRussian:item.DescriptionEnglish;Call(runtime,"BindArchiveArtifactBuilds",card,ru);}
 Check(state.Cards.Count==90,"all artifact cards");foreach(var card in state.Cards){Check(card.Builds!=null,"artifact detail enabled "+card.Id);foreach(var build in card.Builds){Check(build.Members.Count>=2&&build.Members.Select(m=>m.Id).Distinct().Count()==build.Members.Count,"distinct required members");Check(build.Members.Count(m=>m.Selected)==1&&build.Members.Single(m=>m.Selected).Id==card.Id,"selected item marked");Check(!string.IsNullOrWhiteSpace(build.Title)&&!string.IsNullOrWhiteSpace(build.Description),"name and effect");}}
 foreach(var set in CampaignArtifactSets.All)foreach(string id in set.Requires){var card=state.Cards.Single(c=>c.Id=="artifact:"+id);Check(card.Builds.Any(b=>b.Title==(ru?set.Ru:set.En)&&b.Members.Select(m=>m.Id.Substring(9)).SequenceEqual(set.Requires)),"campaign set exact membership "+set.Id);}
 foreach(var set in catalog.Planner.Where(x=>x.category=="artifact-set")){var ids=((List<string>)Call(runtime,"SourceSetArtifacts",set)).ToArray();foreach(string id in ids){var card=state.Cards.Single(c=>c.Id=="artifact:"+id);Check(card.Builds.Any(b=>!b.Combination&&b.Members.Select(m=>m.Id.Substring(9)).SequenceEqual(ids)),"full legacy build membership "+set.id);}}
 foreach(var synergy in catalog.Planner.Where(x=>x.category=="artifact-synergy"))foreach(string id in synergy.requires){var card=state.Cards.Single(c=>c.Id=="artifact:"+id);Check(card.Builds.Any(b=>b.Combination&&b.Members.Select(m=>m.Id.Substring(9)).SequenceEqual(synergy.requires)),"existing combination "+synergy.id);}
 screens.Add(state);}}
 catch{UnityEngine.Object.DestroyImmediate(owner);throw;}
 var host=new GameObject("Owned artifact build screen");var archive=host.AddComponent<NativeArchiveScreen>();var target=new RenderTexture(720,1400,0,RenderTextureFormat.ARGB32);target.Create();int language=0,frames=0,last=-1;double deadline=EditorApplication.timeSinceStartup+120;UIDocument doc=null;VisualElement root=null;EditorApplication.CallbackFunction tick=null;
 void Show(){archive.Show(screens[language],Screen.width/360f,()=>{},_=>{},_=>{});doc=host.GetComponent<UIDocument>();doc.panelSettings.scaleMode=PanelScaleMode.ConstantPixelSize;doc.panelSettings.scale=2;doc.panelSettings.targetTexture=target;root=doc.rootVisualElement;root.style.width=360;root.style.height=700;frames=0;}
 void Finish(string status,string error=null){EditorApplication.update-=tick;doc.panelSettings.targetTexture=null;UnityEngine.Object.DestroyImmediate(host);UnityEngine.Object.DestroyImmediate(owner);target.Release();UnityEngine.Object.DestroyImmediate(target);Directory.CreateDirectory("Library/menu-archive");File.WriteAllText("Library/menu-archive/artifact-builds.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status,checks,error,scope="actual isolated runtime 90 artifact memberships in RU/EN; actual attached archive click and bounded scroll detail; no PlayerPrefs writes"}));}
 Show();Application.runInBackground=true;tick=()=>{try{EditorApplication.QueuePlayerLoopUpdate();if(!Application.isPlaying||EditorApplication.timeSinceStartup>deadline){Finish("FAIL","deadline");return;}if(last==Time.frameCount)return;last=Time.frameCount;frames++;if(frames==20){var card=root.Query<VisualElement>("archive-card").ToList()[0];using(var click=ClickEvent.GetPooled()){click.target=card;card.SendEvent(click);}Check(root.Q("archive-entry-detail")!=null,"tap opens artifact detail");}if(frames<36)return;
 var detail=root.Q("archive-entry-detail");Check(detail.Q("archive-artifact-builds-title")!=null,"build section visible");Check(detail.Query<VisualElement>("archive-build-member").ToList().Count>0,"members with pictures visible");foreach(var label in detail.Query<Label>().ToList()){if(label.worldBound.width<=0)continue;Check(label.worldBound.xMin>=root.worldBound.xMin-1&&label.worldBound.xMax<=root.worldBound.xMax+1,"text horizontal bounds");}
 var prior=RenderTexture.active;var image=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);try{RenderTexture.active=target;image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();Directory.CreateDirectory("Library/menu-archive");File.WriteAllBytes("Library/menu-archive/artifact-builds-"+(language==0?"ru":"en")+".png",image.EncodeToPNG());}finally{RenderTexture.active=prior;UnityEngine.Object.DestroyImmediate(image);}if(++language==2){Finish("PASS");return;}Show();}catch(Exception e){Finish("FAIL",e.ToString());}};EditorApplication.update+=tick;return new{status="queued",checks};
 }
}
